#include <stack>
#include <vector>
#include <deque>

// Example of using vector as the underlying container
using VecStack = std::stack<int, std::vector<int>>;

int main() {
    VecStack s;
    s.push(10); // Calls std::vector::push_back(10)
    int top_val = s.top(); // Calls std::vector::back()
    s.pop(); // Calls std::vector::pop_back()

    // std::list is also valid, provided it satisfies the interface
    std::stack<double, std::list<double>> ls;
    ls.push(3.14);
}
